<template><view class="mine"><image class="waves" src="/static/ui/mine-background.svg" mode="widthFix"/><PageHeader transparent/><view class="profile"><view class="avatar"><image src="/static/ui/unlogin.svg" mode="aspectFit"/><text>V</text></view><text class="name">{{ config.profile_name || 'crow look粉红乌鸦' }}</text></view><view class="menu"><button v-for="item in items" :key="item.label" @click="act(item)"><CrowIcon :name="item.icon"/><text>{{item.label}}</text><view class="arrow"/></button></view><view class="brand-footer"><BrandFooter/></view><AppTabs current="mine"/></view></template>
<script setup>
import CrowIcon from '../../components/CrowIcon.vue';import PageHeader from '../../components/PageHeader.vue';import BrandFooter from '../../components/BrandFooter.vue';import AppTabs from '../../components/AppTabs.vue';import {config} from '../../lib/content';
const items=[{label:'我的点赞',icon:'like-o',page:'favorites'},{label:'联系客服',icon:'chat-o',page:'service'},{label:'总部地址',icon:'location-o',page:'locations'},{label:'清除缓存',icon:'bulb-o'}];const act=i=>{if(i.page)uni.navigateTo({url:`/pages/${i.page}/${i.page}`});else{for(const k of uni.getStorageInfoSync().keys)if(k.startsWith('crowlook:'))uni.removeStorageSync(k);uni.showToast({title:'清除成功'})}}
</script>
<style scoped>.mine{min-height:100vh;padding-bottom:100rpx;position:relative}.waves{position:absolute;left:0;right:0;top:0;height:520rpx;overflow:hidden;background:#fafafa}.waves view{position:absolute;width:150%;height:290rpx;border-radius:50%;left:-25%;background:#f7f7f7;top:20rpx;transform:rotate(13deg)}.waves view:nth-child(2){background:#f2f2f2;top:140rpx;transform:rotate(-11deg)}.waves view:nth-child(3){background:#fff;top:335rpx;height:230rpx;transform:rotate(9deg)}.profile{position:relative;display:flex;flex-direction:column;align-items:center;padding-top:75rpx}.avatar{height:140rpx;width:140rpx;border:5rpx solid #fff;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center;position:relative;box-shadow:0 1rpx 3rpx #ddd}.avatar image{height:140rpx;width:140rpx}.avatar text{position:absolute;bottom:0;right:8rpx;background:#ffc107;border:2rpx solid #fff;color:#fff;font-family:Georgia;font-size:20rpx;font-style:italic;width:31rpx;height:31rpx;border-radius:50%;text-align:center;line-height:29rpx}.name{font-size:29rpx;font-weight:bold;margin-top:30rpx}.menu{margin:134rpx 40rpx 0}.menu button{height:116rpx;background:transparent;margin:0;padding:0 14rpx;display:flex;align-items:center;border-radius:0;border-bottom:1rpx solid #e8e8e8;text-align:left;gap:20rpx;font-size:25rpx;color:#333}.menu .crow-icon{font-size:20px;width:50rpx;text-align:center;margin-right:0;opacity:.5}.menu text{flex:1}.arrow{height:15rpx;width:15rpx;border-top:2rpx solid #aaa;border-right:2rpx solid #aaa;transform:rotate(45deg);margin-right:3rpx}.brand-footer{position:absolute;bottom:100rpx;left:0;right:0}.brand-footer :deep(.footer){padding-bottom:50rpx}
@media(max-height:680px){.brand-footer{position:relative;bottom:auto}.menu{margin-top:80rpx}}
</style>
